<?php declare(strict_types=1);require_once __DIR__.'/includes/header.php';require_csrf();$errors=[];$success=false;if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf())$errors[]='Your security token is invalid.';$name=trim((string)($_POST['name']??''));$email=normalize_email((string)($_POST['email']??''));$category=(string)($_POST['category']??'');$message=trim((string)($_POST['message']??''));if(strlen($name)<2)$errors[]='Enter your full name.';if(!validate_email($email))$errors[]='Enter a valid email address.';if(!in_array($category,['Business','Partnership','General Inquiry'],true))$errors[]='Select a valid category.';if(strlen($message)<20)$errors[]='Please provide more detail.';if(!$errors){$entries=load_json('contact.json',[]);$entries[]= ['id'=>bin2hex(random_bytes(16)),'name'=>$name,'email'=>$email,'category'=>$category,'message'=>$message,'created_at'=>date('c')];if(save_json('contact.json',$entries))$success=true;else$errors[]='Your message could not be saved.';}}?><main><section class="page-hero"><div class="container"><div class="breadcrumb"><a href="<?= e(app_url('index.php')) ?>">Home</a><span>/</span><span>Contact</span></div><div class="eyebrow">Connect with 2B2X</div><h1>Start a conversation.</h1><p>For partnership, business, or general inquiries, send a message directly to the team.</p></div></section><section class="section"><div class="container contact-layout"><aside class="contact-aside reveal" data-reveal><div class="section-kicker">Company details</div><h3>Built by people who care about the details.</h3><p>2B2X is an independent browser product focused on thoughtful software and a clear operating experience.</p><a href="mailto:hello@2b2x.local">hello@2b2x.local</a><span>Business hours: Monday–Friday</span><span>Windows-first product</span></aside><div class="form-card reveal reveal-delay-1" data-reveal><div class="section-kicker">Contact form</div><h2 style="margin:0 0 8px;font-size:34px">Tell us what you need.</h2><form action="<?= e(app_url('contact.php')) ?>" method=post data-validate><input type=hidden name=csrf_token value="<?= e(csrf_token()) ?>"><div class="form-grid"><div class="field"><label for=name>Name</label><input id=name name=name required autocomplete=name></div><div class="field"><label for=email>Email</label><input id=email name=email type=email required autocomplete=email></div><div class="field full"><label for=category>Inquiry type</label><select id=category name=category required><option value=>Choose a category</option><option>Business</option><option>Partnership</option><option>General Inquiry</option></select></div><div class="field full"><label for=message>Message</label><textarea id=message name=message required></textarea></div></div><?php if($success):?><div class="alert success" style="margin-top:16px">Your message was received. Thank you for reaching out.</div><?php elseif($errors):?><div class="alert error" style="margin-top:16px"><?= e(implode(' ',array_slice($errors,0,3))) ?></div><?php endif;?><div class="form-submit-row"><small>We use your information only to respond to this inquiry.</small><button class="button button-primary" type=submit>Send message <span class=arrow>↗</span></button></div></form></div></div></section></main><?php require_once __DIR__.'/includes/footer.php'; ?>
